/// <reference types="react" />
import { type DynamicDataLoaderProps } from '../dynamic-data-loader/types';
export type JSXElement = JSX.Element;
export interface DynamicDataInfo {
    /**
     * Flag to indicate if the value is dynamic or not.
     */
    isDynamic: boolean;
    /**
     * Flag to indicate if there was an error while fetching the dynamic data.
     */
    isError: boolean;
    /**
     * Flag to indicate if the dynamic data is still loading.
     */
    isLoading: boolean;
    /**
     * The resolved value of the dynamic data.
     *
     * - It will be a `null` when the `isLoading` is true and `isDynamic` is true at initial render.
     * - It will be a `null` when the `isError` is true.
     * - It will be the original value when the `isDynamic` is false.
     */
    resolvedValue: string;
}
export interface DynamicDataProps extends DynamicDataLoaderProps {
    /**
     * The value to be computed to get the dynamic data.
     */
    value: string;
    /**
     * The children function where the dynamic data will be passed.
     *
     * @param {DynamicDataInfo} info The dynamic data info.
     *
     * @returns {JSXElement}
     */
    children: (info: DynamicDataInfo) => JSXElement;
    /**
     * Flag to indicate if the loader should be shown or not.
     */
    showLoader?: boolean;
}
